const STANDING_PERMS: Record<(typeof PERM_ACTIONS)[number], string> = {
  open: 'clerk,steward', settle: 'clerk,steward', void: 'clerk,steward', reassign: 'steward', close: 'clerk,steward', reopen: 'steward',
};

type PermKey = `perm-${(typeof PERM_ACTIONS)[number]}`;

type Key = 'clerk-limit' | 'floor' | 'terms' | 'terms-A' | 'terms-B' | 'terms-C' | 'grace-A' | 'grace-B' | 'grace-C' | 'late-pct' | 'policy-date' | 'period-numbering-from' | 'cap' | 'proof-threshold' | 'proof-threshold-A' | 'proof-threshold-B' | 'proof-threshold-C' | 'note-threshold' | 'review-threshold' | 'grace-days' | 'escalate-after' | 'review-sla' | 'entry-date' | 'pot' | 'alert-threshold' | 'parent' | 'fiscal-start-month' | 'rounding' | 'proof-kinds' | 'default-grade' | PermKey;

const GRADES = ['A', 'B', 'C'] as const;

/** The settings that carry a figure: each is saved from a from-date (blank for the sheet's today). */
type DatedKey = Exclude<Key, 'policy-date' | 'period-numbering-from' | 'grace-days' | 'escalate-after' | 'review-sla' | 'entry-date' | 'pot' | 'alert-threshold' | 'parent' | 'fiscal-start-month' | 'proof-kinds' | 'default-grade' | PermKey>;

const NO_FROM: Record<DatedKey, string> = { 'clerk-limit': '', floor: '', terms: '', 'terms-A': '', 'terms-B': '', 'terms-C': '', 'grace-A': '', 'grace-B': '', 'grace-C': '', 'late-pct': '', cap: '', 'proof-threshold': '', 'proof-threshold-A': '', 'proof-threshold-B': '', 'proof-threshold-C': '', 'note-threshold': '', 'review-threshold': '', rounding: '' };

const isDated = (k: Key): k is DatedKey => k in NO_FROM;

// The sheet's settings in force, and the form that changes them: the clerk limit (blank for none),
// the floor (blank for its default), the terms in days (blank for 14), each grade's own terms (blank
// for the sheet's terms), each grade's grace days (blank for none: whole days after its due-by a claim of
// a person of the grade on its date is not yet overdue, and its late charge counts from) and the late percent (blank for
// 0.00), the policy date rounding turns on (blank for the sheet's today) and the date claims opened
// are numbered per period from (blank for off), and the cap on a person's due-total (blank for none), and the proof threshold above which a claim's due needs a proof to be settled or approved (blank for none), and each grade's own proof threshold, which a claim of a person of the grade on its date takes instead (blank for none: the sheet's), and the note threshold above which a claim's due needs a note to be opened (blank for none), and the review threshold above which a claim's due sends it to REVIEW when opened (blank for none). Saving changes the setting last touched, so a field left blank does not clear the others.
// Each setting that carries a figure is saved from its from-date (blank for the sheet's today), and shows
// the value in force on the sheet's today; the policy date and period numbering date are not dated.
// The permission matrix gives, for each action, the roles that may take it, comma separated (blank keeps
// the standing rule, shown as the placeholder); it is not dated. The grace days (blank for off, not
// dated) are the whole days after its to-date an open period is closed when the sheet's today moves.
// The escalation gap (blank for off, not dated) is the whole days at least between a claim's previous reminder
// and the sheet's today for a reminder to escalate it, once per claim.
// The review SLA (blank for none, not dated) is the whole days after its review day a claim in REVIEW may stay
// there; past them it shows as review-late.
// The entry date (blank for off, not dated) is the default date of a new claim in place of the sheet's today.
// The pot (blank for none, not dated) is shared out among each balanced pool's members by their shares.
// The alert threshold (blank for off, not dated) is the due-total above which a person a change takes there
// raises an ALERT in the audit file.
// The parent (a sheet id, blank for none, not dated) is the sheet whose rates a grade with no rate in force on a
// date takes, then its parent's, up to three levels up.
// The rounding mode (half-up or half-even, blank for none) is saved from its from-date; a claim whose date has
// one in force rounds its live figures by it, else by the policy date.
// The default grade (A, B or C, blank for A, not dated) is the grade the quick-add bar and an import line with a
// blank grade give a new person.
// The fiscal start month (1 to 12, not dated) is the month a fiscal year starts in; 1 unless set.
// The proof kinds (receipt, photo; comma separated, blank for none, not dated) are the kinds a claim above its proof
// threshold needs at least one proof of each of before it is settled or approved.
function SheetSettings() {
  const fig = useFigure();
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const settings = useSettings(sheet);
  const [values, setValues] = useState<Record<Key, string>>({ 'clerk-limit': '', floor: '', terms: '', 'terms-A': '', 'terms-B': '', 'terms-C': '', 'grace-A': '', 'grace-B': '', 'grace-C': '', 'late-pct': '', 'policy-date': '', 'period-numbering-from': '', cap: '', 'proof-threshold': '', 'proof-threshold-A': '', 'proof-threshold-B': '', 'proof-threshold-C': '', 'note-threshold': '', 'review-threshold': '', 'grace-days': '', 'escalate-after': '', 'review-sla': '', 'entry-date': '', pot: '', 'alert-threshold': '', parent: '', 'fiscal-start-month': '', rounding: '', 'proof-kinds': '', 'default-grade': '',
    'perm-open': '', 'perm-settle': '', 'perm-void': '', 'perm-reassign': '', 'perm-close': '', 'perm-reopen': '' });
  const [froms, setFroms] = useState<Record<DatedKey, string>>(NO_FROM);
  const [key, setKey] = useState<Key>('clerk-limit');
  const queryClient = useQueryClient();

  const save = useMutation({
    mutationFn: ({ key, value, from }: { key: Key; value: string; from: string }) =>
      postJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`, { key, value, from, user }),
    onSuccess: async (_, { key }) => {
      await queryClient.invalidateQueries({ queryKey: settingsKey(sheet) });
      if (key === 'pot') await queryClient.invalidateQueries({ queryKey: poolsKey(sheet) });
      if (key === 'parent') await queryClient.invalidateQueries({ queryKey: ratesKey(sheet) });
      setValues((v) => ({ ...v, [key]: '' }));
      if (isDated(key)) setFroms((f) => ({ ...f, [key]: '' }));
    },
  });
  const submit = useSubmitOnce(save);

  const field = (k: Key, placeholder: string, inputMode: 'decimal' | 'text' = 'decimal') => (
    <input
      data-testid={`setting-${k}`}
      placeholder={placeholder}
      inputMode={inputMode}
      value={values[k]}
      onFocus={() => setKey(k)}
      onChange={(e) => {
        setValues({ ...values, [k]: e.target.value });
        setKey(k);
        save.reset();
      }}
    />
  );

  const from = (k: DatedKey) => (
    <input
      data-testid={`setting-${k}-from`}
      placeholder="From YYYY-MM-DD (blank for today)"
      value={froms[k]}
      onFocus={() => setKey(k)}
      onChange={(e) => {
        setFroms({ ...froms, [k]: e.target.value });
        setKey(k);
        save.reset();
      }}
    />
  );

import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';

/** The sheet's settings: `clerkLimit` (two decimals) is the most due a clerk may settle a claim at,
 *  null for no limit; `floor` (two decimals) is the least a claim's live due may be; `terms` is the
 *  business days after its date a claim is due by; `latePct` (two decimals) is the percent of an overdue
 *  claim's figure plus its earlier charges (compounding) charged at each full 30 days it is overdue (the one in force on that boundary); `policyDate` (yyyy-MM-dd) is the date
 *  rounding turns on, null when blank (then the sheet's today); `periodNumberingFrom` (yyyy-MM-dd) is the
 *  date from which claims opened are numbered per period, null when blank (off); `gradeTerms` is the terms
 *  in force for each grade (its own, else the sheet's), by grade; `cap` (two decimals) is the most a person's
 *  due-total may be, null for no cap; `proofThreshold` (two decimals) is the due above which a claim needs a proof
 *  before it is settled or approved, null for none; `noteThreshold` (two decimals) is the due above which a
 *  claim needs a note before it is opened, null for none. Each of these that carries a figure is the one in force on the sheet's today.
 *  `floorFrom` and `latePctFrom` are the floor and late percent recorded, oldest from-date (yyyy-MM-dd) first:
 *  a claim's floor and late percent are those in force on its date. `perms` is the permission matrix: the roles
 *  that may take each action (open, settle, void, reassign, close, reopen), comma separated, by action; null when
 *  blank (the standing rule). `graceDays` is the whole days after its to-date an open period is closed when the
 *  sheet's today moves, null when blank (off). `entryDate` (yyyy-MM-dd) is the default date of a new claim
 *  in place of the sheet's today, null when blank (off). `gradeGrace` is each grade's grace days in force on the sheet's
 *  today, by grade, null when it has none; `gradeGraceFrom` is each grade's grace days recorded, by grade, oldest
 *  from-date first: a claim's grace is the one in force on its date for its person's grade then. `gradeProofThreshold`
 *  is each grade's proof threshold in force on the sheet's today, by grade, null when it has none (then the sheet's).
 *  `pot` (two decimals) is the sum a balanced pool shares out among its members, null for none; it is not dated.
 *  `parent` is the id of the sheet whose rates a grade with no rate in force on a date takes (then its parent's, up
 *  to three levels up), null for none; it is not dated. `fiscalStartMonth` is the month (1 to 12) a fiscal year starts in,
 *  1 unless set; it is not dated. `alertThreshold` (two decimals) is the due-total above which a person
 *  crossing it raises an ALERT, null for off; it is not dated. `rounding` is the rounding mode in force on
 *  the sheet's today (half-up or half-even), null for none; `roundingFrom` is the modes recorded, oldest from-date
 *  first (a claim rounds by the one in force on its date, else by the policy date). `reviewThreshold` (two decimals)
 *  is the due above which a claim goes to REVIEW when opened, in force on the sheet's today, null for none.
 *  `escalateAfter` is the whole days at least between a claim's previous reminder and the sheet's today for a reminder
 *  to escalate it (once per claim), null for off; it is not dated. `reviewSla` is the whole days after its review day
 *  a claim in REVIEW may stay there before it is late, null for none; it is not dated. `proofKinds` is the kinds of proof
 *  (receipt, photo), comma separated, a claim above its proof threshold needs one of each of before it is settled or
 *  approved, null for none; it is not dated. `defaultGrade` is the grade the quick-add bar and an import line with a
 *  blank grade give a new person, null when blank (then A); it is not dated. */
export type Settings = { clerkLimit: string | null; floor: string; terms: string; latePct: string; policyDate: string | null;
  periodNumberingFrom: string | null; gradeTerms: Record<string, string>; cap: string | null; proofThreshold: string | null;
  floorFrom: Dated[]; latePctFrom: Dated[]; perms: Record<string, string | null>;
  graceDays: string | null; noteThreshold: string | null; entryDate: string | null;
  gradeGrace: Record<string, string | null>; gradeGraceFrom: Record<string, Dated[]>;
  gradeProofThreshold: Record<string, string | null>; pot: string | null; parent: string | null; fiscalStartMonth: string;
  alertThreshold: string | null; rounding: string | null; roundingFrom: Dated[]; reviewThreshold: string | null;
  escalateAfter: string | null; reviewSla: string | null; proofKinds: string | null; defaultGrade: string | null };

/** A setting's value recorded from a date (yyyy-MM-dd); a null value is blank. */
export type Dated = { from: string; value: string | null };

